//! Evens out how loud each General MIDI program sounds in the bundled
//! GeneralUser GS soundfont, so parts at the same volume play at about the
//! same loudness whichever sound they use (its shamisen is ~10 dB quieter
//! than its piano, its strings ~2 dB louder).
//!
//! Applied only where that soundfont is played (WAV/MP3 rendering), as a
//! CC11 (expression) attenuation sent with each program change: the MIDI
//! export stays soundfont-neutral, and the part's own volume keeps CC7.

/// Each program's loudness in GeneralUser GS, in dB relative to program 0.
/// Generated by `cargo test --release --features wav --lib
/// regenerate_program_loudness_table -- --ignored`.
const PROGRAM_LOUDNESS_DB: [f32; 128] = include!("wav_loudness_table.rs");

/// The largest value a MIDI data byte can hold.
const MAX_MIDI_DATA_BYTE: f32 = 127.0;

/// The CC11 value that brings `program` down to the quietest program's
/// loudness (expression can only attenuate). The synth's expression curve
/// is 40·log10(value/127) dB. The rendered audio is peak-normalized
/// afterwards, so only the balance between parts changes, not the overall
/// level.
pub(super) fn balancing_expression(program: u8) -> u8 {
    let quietest_db = PROGRAM_LOUDNESS_DB
        .iter()
        .copied()
        .fold(f32::INFINITY, f32::min);
    let loudness_db = PROGRAM_LOUDNESS_DB
        .get(usize::from(program))
        .copied()
        .unwrap_or(quietest_db);
    let attenuation_db = quietest_db - loudness_db;
    (MAX_MIDI_DATA_BYTE * 10f32.powf(attenuation_db / 40.0)).round() as u8
}
